package com.android.purebilibili.core.store

import com.bilipai.desktop.ui.DesktopOriginalPlayerSettingsContext
import com.bilipai.desktop.ui.DesktopOriginalPlayerSettingsDataStore
import com.bilipai.desktop.ui.playerBooleanPreferencesKey
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

/** Original key/getter over the existing Root Store; no independent preference cache. */
internal object DesktopOriginalNextWatchHintSettings {
    private val KEY_NEXT_WATCH_HINT_ENABLED = playerBooleanPreferencesKey("next_watch_hint_enabled")

    fun getNextWatchHintEnabled(context: DesktopOriginalPlayerSettingsContext): Flow<Boolean> = DesktopOriginalPlayerSettingsDataStore(context).data
        .map { preferences -> preferences[KEY_NEXT_WATCH_HINT_ENABLED] ?: true }
}
